```javascript
// Improved version with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(mongoSanitize()); // Sanitize query parameters, body, etc. against MongoDB operator injection
app.use(xss()); // Sanitize user input from request body, query, and params
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
