/*
Suggested improvements for app.js with enhanced error handling and security
*/

// Install required dependencies first:
// npm install express helmet cors express-validator rate-limiter-flexible

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const { rateLimit } = require('rate-limiter-flexible');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || '*', // Restrict in production
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});

app.use(limiter);

// Middleware to parse JSON with size limit
app.use(express.json({
  limit: '10kb' // Prevent large payloads
}));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

// Users endpoint with potential ID parameter (future-proofed)
app.get('/users', [
  // Validate query parameters if they exist
  (req, res, next) => {
    if (req.query.id) {
      const id = parseInt(req.query.id);
      if (isNaN(id) || id <= 0) {
        return res.status(400).json({
          error: 'Invalid user ID parameter'
        });
      }
    }
    next();
  }
], (req, res) => {
  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Filter by ID if specified
  if (req.query.id) {
    const id = parseInt(req.query.id);
    users = users.filter(user => user.id === id);

    if (users.length === 0) {
      return res.status(404).json({
        error: 'User not found'
      });
    }
  }

  res.json(users);
});

// Example POST endpoint with validation (demonstrating input validation)
app.post('/users', [
  // Validate and sanitize input
  body('name').trim().escape().notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters'),
  body('email').isEmail().normalizeEmail()
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array() 
    });
  }

  // Process valid data
  // (In a real app, you'd save to database)

  res.status(201).json({
    message: 'User created successfully',
    user: req.body
  });
});

// Global error handler middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({
    error: 'Something went wrong!'
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

// Server startup with error handling
const PORT = process.env.PORT || 3000;

let server;

try {
  server = app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Handle server errors
  server.on('error', (error) => {
    console.error('Server error:', error);
    process.exit(1);
  });

} catch (error) {
  console.error('Failed to start server:', error);
  process.exit(1);
}

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (error) => {
  console.error('Unhandled Rejection:', error);
  process.exit(1);
});

module.exports = app;

const { Client } = require('pg');
const https = require('https');

// Get environment variables
const DATABASE_URL = process.env.DATABASE_URL;
const ANTHROPIC_API_KEY = process.env.ANTHROPIC_API_KEY;
const STRIPE_SECRET_KEY = process.env.STRIPE_SECRET_KEY;
const AWS_ACCESS_KEY_ID = process.env.AWS_ACCESS_KEY_ID;
const AWS_SECRET_ACCESS_KEY = process.env.AWS_SECRET_ACCESS_KEY;

async function verifyDatabaseConnection() {
  console.log('\n🔍 Verifying database connection...');

  if (!DATABASE_URL) {
    console.log('❌ DATABASE_URL not set in environment');
    return false;
  }

  const client = new Client({ connectionString: DATABASE_URL });

  try {
    await client.connect();
    const result = await client.query('SELECT now()');
    console.log(`✅ Database connected successfully: ${result.rows[0].now}`);
    await client.end();
    return true;
  } catch (error) {
    console.log(`❌ Database connection failed: ${error.message}`);
    return false;
  }
}

function verifyAnthropicKey() {
  return new Promise((resolve) => {
    console.log('\n🔍 Verifying Anthropic API key...');

    if (!ANTHROPIC_API_KEY) {
      console.log('❌ ANTHROPIC_API_KEY not set in environment');
      resolve(false);
      return;
    }

    const options = {
      hostname: 'api.anthropic.com',
      path: '/v1/complete',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-API-Key': ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01'
      }
    };

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode === 401) {
          console.log('❌ Invalid Anthropic API key');
          resolve(false);
        } else if (res.statusCode === 403) {
          console.log('❌ Anthropic API key is forbidden');
          resolve(false);
        } else if (res.statusCode === 200) {
          console.log('✅ Anthropic API key is valid (note: would have generated a response)');
          resolve(true);
        } else {
          console.log(`⚠️ Anthropic API returned unexpected status: ${res.statusCode}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ Anthropic API request failed: ${error.message}`);
      resolve(false);
    });

    // Send minimal request body - we expect an error about missing required fields
    // but this will verify the API key is valid
    req.write(JSON.stringify({
      prompt: '\n\n',
      model: 'claude-2.1',
      max_tokens_to_sample: 1
    }));
    req.end();
  });
}

function verifyStripeKey() {
  return new Promise((resolve) => {
    console.log('\n🔍 Verifying Stripe API key...');

    if (!STRIPE_SECRET_KEY) {
      console.log('❌ STRIPE_SECRET_KEY not set in environment');
      resolve(false);
      return;
    }

    const options = {
      hostname: 'api.stripe.com',
      path: '/v1/account',
      method: 'GET',
      auth: `${STRIPE_SECRET_KEY}:`
    };

    const req = https.request(options, (res) => {
      if (res.statusCode === 200) {
        console.log('✅ Stripe API key is valid');
        resolve(true);
      } else if (res.statusCode === 401) {
        console.log('❌ Invalid Stripe API key');
        resolve(false);
      } else {
        console.log(`⚠️ Stripe API returned unexpected status: ${res.statusCode}`);
        resolve(false);
      }
    });

    req.on('error', (error) => {
      console.log(`❌ Stripe API request failed: ${error.message}`);
      resolve(false);
    });

    req.end();
  });
}

async function main() {
  console.log('🔐 Verifying credentials from environment...');

  // Load .env.test file
  require('dotenv').config({ path: './.env.test' });

  const results = {
    database: await verifyDatabaseConnection(),
    anthropic: await verifyAnthropicKey(),
    stripe: await verifyStripeKey()
  };

  // AWS verification is more complex and would require the AWS SDK
  // and potentially cost money to make test requests
  console.log('\n📝 AWS credentials were not tested (requires AWS SDK and potential costs)');

  console.log('\n📊 Summary:');
  console.log(`Database: ${results.database ? '✅ VALID' : '❌ INVALID'}`);
  console.log(`Anthropic API: ${results.anthropic ? '✅ VALID' : '❌ INVALID'}`);
  console.log(`Stripe: ${results.stripe ? '✅ VALID' : '❌ INVALID'}`);

  const validCount = Object.values(results).filter(Boolean).length;
  const totalCount = Object.keys(results).length;

  if (validCount === 0) {
    console.log('\n❌ All tested credentials are invalid!');
    process.exit(1);
  } else if (validCount < totalCount) {
    console.log(`\n⚠️ ${validCount} out of ${totalCount} tested credentials are valid`);
    process.exit(0);
  } else {
    console.log(`\n✅ All ${totalCount} tested credentials are valid!`);
    process.exit(0);
  }
}

main().catch(err => {
  console.error('Unexpected error:', err);
  process.exit(1);
});

