async function verifyDatabase() {
  console.log('Verifying database connection...');

  try {
    const client = new Client({
      connectionString: process.env.DATABASE_URL,
      ssl: false // Using internal network
    });

    await client.connect();
    const result = await client.query('SELECT version();');
    console.log('✅ Database connection successful');
    console.log('   Version:', result.rows[0].version);
    await client.end();
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

function verifyApiKey(url, apiKey, name) {
  return new Promise((resolve) => {
    console.log(`Verifying ${name} API key...`);

    const options = {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json'
      }
    };

    const req = https.request(url, options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 401) {
          // 401 means the service is reachable but credentials are invalid
          // 200 means valid credentials
          console.log(res.statusCode === 200 ? `✅ ${name} API reachable` : `❌ ${name} API key invalid`);
          resolve(res.statusCode === 200);
        } else {
          console.log(`❌ ${name} API unexpected response: ${res.statusCode}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${name} API request failed:`, error.message);
      resolve(false);
    });

    req.setTimeout(10000, () => {
      req.destroy();
      console.log(`❌ ${name} API request timed out`);
      resolve(false);
    });

    req.end();
  });
}

