function verifyApiKey(url, apiKey, name) {
  return new Promise((resolve) => {
    console.log(`Verifying ${name} API key...`);

    const options = {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json'
      }
    };

    const req = https.request(url, options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 401) {
          // 401 means the service is reachable but credentials are invalid
          // 200 means valid credentials
          console.log(res.statusCode === 200 ? `✅ ${name} API reachable` : `❌ ${name} API key invalid`);
          resolve(res.statusCode === 200);
