const { Pool } = require('pg');
const https = require('https');

// Load environment variables
require('dotenv').config({ path: '.env.test' });

const results = {};

// Test Database Connection
async function testDatabase() {
  const pool = new Pool({
    connectionString: process.env.DATABASE_URL,
    ssl: { rejectUnauthorized: false } // For testing internal DB
  });

  try {
    const client = await pool.connect();
    await client.query('SELECT NOW()');
    client.release();
    results.database = 'SUCCESS';
    console.log('✅ Database: Connection successful');
  } catch (err) {
    results.database = `FAIL: ${err.message}`;
    console.log('❌ Database:', err.message);
  } finally {
    await pool.end();
  }
}

// Test API Keys
function testApiKey(service, host, apiKey, path = '/v1/models') {
  return new Promise((resolve) => {
    const options = {
      hostname: host,
      port: 443,
      path: path,
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`
      }
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        if (res.statusCode === 200) {
          results[service] = 'SUCCESS';
          console.log(`✅ ${service}: Valid API key`);
        } else {
          results[service] = `FAIL: HTTP ${res.statusCode}`;
          console.log(`❌ ${service}: HTTP ${res.statusCode}`);
        }
        resolve();
      });
    });

    req.on('error', (err) => {
      results[service] = `FAIL: ${err.message}`;
      console.log(`❌ ${service}:`, err.message);
      resolve();
    });

    req.end();
  });
}

// Run tests
(async () => {
  console.log('🔬 Testing credentials from .env.test...\n');

  await testDatabase();

  await testApiKey('Anthropic', 'api.anthropic.com', process.env.ANTHROPIC_API_KEY);
  await testApiKey('Stripe', 'api.stripe.com', process.env.STRIPE_SECRET_KEY, '/v1/account');
  await testApiKey('Logfire', 'api.logfire.sh', process.env.LOGFIRE_TOKEN, '/v1/projects');

  // AWS test is different (uses AWS SDK signature)
  console.log('⚠️  AWS: Cannot test with HTTP request, requires AWS SDK');
  results.aws = 'SKIPPED';

  // Write results
  await require('fs').promises.writeFile('test-results.json', JSON.stringify(results, null, 2));
  console.log('\n📝 Results written to test-results.json');
})();

