    if (page && (!Number.isInteger(Number(page)) || Number(page) < 1)) {
      return res.status(400).json({
        error: 'Invalid page parameter. Must be a positive integer.'
      });
    }

    if (limit && (!Number.isInteger(Number(limit)) || Number(limit) < 1 || Number(limit) > 100)) {
      return res.status(400).json({
        error: 'Invalid limit parameter. Must be a positive integer between 1 and 100.'
      });
    }

    next();
  }
], (req, res) => {
  try {
    // Simulate pagination if requested
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const startIndex = (page - 1) * limit;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // In a real application, this would be paginated from a database
    const results = users.slice(startIndex, startIndex + limit);

    res.json({
      results,
      pagination: {
        page,
        limit,
        total: users.length,
        pages: Math.ceil(users.length / limit)
      }
    });
  } catch (error) {
    logger.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  logger.warn(`404 - ${req.method} ${req.path} - ${req.ip}`);
  res.status(404).json({
    error: 'Route not found'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error('Uncaught error:', err);

  // Prevent stack traces in production
  if (process.env.NODE_ENV === 'production') {
    res.status(500).json({
      error: 'Internal server error'
    });
