// Security middleware and configuration

const express = require('express');
const cors = require('cors');

// Create middleware instances with secure configurations

// CORS configuration - restrict to known, secure origins
const corsOptions = {
  origin: ['http://localhost:3000'], // Adjust to your legitimate frontend origins
  optionsSuccessStatus: 200 // For legacy browser support
};

// Basic security headers middleware
const securityHeaders = (req, res, next) => {
  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');
  // Prevent page from being displayed in an iframe (clickjacking protection)
  res.setHeader('X-Frame-Options', 'DENY');
  // Enable XSS protection in browsers
  res.setHeader('X-XSS-Protection', '1; mode=block');
  // Disable feature detection for reduced attack surface
  res.removeHeader('X-Powered-By');
  next();
};

module.exports = {
  corsMiddleware: cors(corsOptions),
  securityHeaders
};

// Input validation and sanitization utilities

const validator = require('validator');

/**
 * Validates and sanitizes a user ID parameter
 * @param {string|number} id - The user ID to validate
 * @returns {number|undefined} - Returns the parsed integer ID if valid, undefined otherwise
 */
function validateUserId(id) {
  // Check if id is null, undefined, or empty string
  if (id == null || id === '') {
    return undefined;
  }

  // Convert to number
  const numId = Number(id);

  // Check if it's a valid number and a positive integer
  if (Number.isInteger(numId) && numId > 0 && numId <= Number.MAX_SAFE_INTEGER) {
    return numId;
  }

  return undefined;
}

/**
 * Validates an email address
 * @param {string} email - The email to validate
 * @returns {string|undefined} - Returns the sanitized email if valid, undefined otherwise
 */
function validateEmail(email) {
  if (typeof email !== 'string') {
    return undefined;
  }

  // Trim whitespace and convert to lowercase
  const sanitized = email.trim().toLowerCase();

  // Use validator library to check email format
  if (validator.isEmail(sanitized)) {
    return sanitized;
  }

  return undefined;
}

/**
 * Validates a user name
 * @param {string} name - The name to validate
 * @returns {string|undefined} - Returns the sanitized name if valid, undefined otherwise
 */
function validateName(name) {
  if (typeof name !== 'string') {
    return undefined;
  }

  // Trim whitespace and limit length
  const sanitized = name.trim();

  // Basic length validation
  if (sanitized.length === 0 || sanitized.length > 100) {
    return undefined;
  }

  // Optional: Add more specific validation rules as needed
  // For example, disallow certain characters
  if (/[^a-zA-Z0-9\s\-']/.test(sanitized)) {
    return undefined;
  }

  return sanitized;
}

module.exports = {
  validateUserId,
  validateEmail,
  validateName
};

// Centralized error handling middleware

/**
 * Centralized error handler middleware
 * Should be used as the last middleware in the stack
 * @param {Error} err - The error object
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Express next function
 */
function errorHandler(err, req, res, next) {
  // Log the error (in production, use a logging service)
  console.error('Error occurred:', err.stack || err.message || err);

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Create error response
  const errorResponse = {
    success: false,
    message: process.env.NODE_ENV === 'production' 
      ? 'An error occurred' 
      : err.message || 'An error occurred'
  };

  // Add stack trace only in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
  }

  // Set response status and send
  res.status(statusCode).json(errorResponse);
}

/**
 * Middleware to catch 404 errors for undefined routes
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Express next function
 */
function notFoundHandler(req, res, next) {
  const error = new Error(`Route ${req.originalUrl} not found`);
  error.status = 404;
  next(error);
}

module.exports = {
  errorHandler,
  notFoundHandler
};

