const express = require('express');
// Security and utility imports
const { errorHandler, notFoundHandler } = require('./error-handler');
const { corsMiddleware, securityHeaders } = require('./security-config');
const { validateUserId } = require('./validation');

const app = express();

// Apply security middleware
app.use(securityHeaders);
app.use(corsMiddleware);

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example of a parameterized route with validation (not in original but demonstrating best practice)
app.get('/users/:id', (req, res, next) => {
  try {
    const userId = validateUserId(req.params.id);

    if (!userId) {
      const err = new Error('Invalid user ID');
      err.status = 400;
      throw err;
    }

    // In a real app, you would query your database here
    // For this example, we'll just return a success message
    res.json({ 
      success: true, 
      message: `User ${userId} retrieved successfully` 
    });

  } catch (error) {
    // Pass errors to the centralized error handler
    next(error);
  }
});

// Handle undefined routes - should be after all other routes
app.use(notFoundHandler);

// Centralized error handling middleware - should be the last middleware
app.use(errorHandler);

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

