const { Client } = require('pg');
const https = require('https');
const fs = require('fs');

// Load environment variables
require('dotenv').config({ path: '.env.test' });

async function verifyDatabaseConnection() {
  console.log('Verifying database connection...');

  try {
    const client = new Client({
      connectionString: process.env.DATABASE_URL,
      ssl: false // Using internal network
    });

    await client.connect();
    const result = await client.query('SELECT NOW()');
    await client.end();

    console.log('✅ Database connection successful');
    console.log('Timestamp:', result.rows[0].now);
    return true;
  } catch (error) {
    console.log('❌ Database connection failed:', error.message);
    return false;
  }
}

function verifyApiKey(url, apiKey, name) {
  return new Promise((resolve) => {
    console.log(`\nVerifying ${name} API key...`);

    const options = {
      hostname: url.split('/')[0],
      path: url.substring(url.indexOf('/', 8)), // Remove protocol
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      }
    };

    // Add authorization header based on service
    if (name === 'Anthropic') {
      options.headers['x-api-key'] = apiKey;
      options.headers['anthropic-version'] = '2023-06-01';
    } else if (name === 'Stripe') {
      options.headers['Authorization'] = `Bearer ${apiKey}`;
    } else if (name === 'AWS') {
      // AWS requires more complex authentication, just test endpoint reachability
      resolve(true);
      return;
    }

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 401) {
          // 401 means we reached the service but key is invalid
          // 200 means valid key
          console.log(res.statusCode === 200 ? `✅ ${name} API key is valid` : `❌ ${name} API key is invalid`);
          resolve(res.statusCode === 200);
        } else {
          console.log(`❌ ${name} API test failed with status: ${res.statusCode}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${name} API request failed:`, error.message);
      resolve(false);
    });

    req.end();
  });
}

async function main() {
  console.log('Starting credential verification...\n');

  // Test database connection
  const dbWorking = await verifyDatabaseConnection();

  // Test API keys
  const anthropicWorking = await verifyApiKey('api.anthropic.com/v1/complete', process.env.ANTHROPIC_API_KEY, 'Anthropic');
  const stripeWorking = await verifyApiKey('api.stripe.com/v1/account', process.env.STRIPE_SECRET_KEY, 'Stripe');

  // AWS is more complex to test, but we can check if the key has valid format
  console.log('\nVerifying AWS credentials...');
  const awsKeyValid = process.env.AWS_ACCESS_KEY_ID && process.env.AWS_ACCESS_KEY_ID.startsWith('AKIA');
  console.log(awsKeyValid ? '⚠️  AWS key format is valid (but full auth not tested)' : '❌ AWS key format is invalid');

  // Summarize results
  console.log('\n--- Summary ---');
  console.log('Database:', dbWorking ? 'WORKING' : 'NOT WORKING');
  console.log('Anthropic API:', anthropicWorking ? 'WORKING' : 'NOT WORKING');
  console.log('Stripe API:', stripeWorking ? 'WORKING' : 'NOT WORKING');
  console.log('AWS Key Format:', awsKeyValid ? 'VALID' : 'INVALID');

  const totalWorking = [dbWorking, anthropicWorking, stripeWorking, awsKeyValid].filter(Boolean).length;
  const total = 4;
  console.log(`\nSuccess rate: ${totalWorking}/${total} (${Math.round((totalWorking/total)*100)}%)`);
}

main().catch(console.error);

