  const match = dbUrl.match(/postgres:\/\/(.*?):(.*?)@([\w\.-]+):([\d]+)\//);
  if (!match) {
    console.log('❌ Could not parse DATABASE_URL');
    return;
  }

  const [, username, password, host, port] = match;
  console.log(`Attempting to connect to ${host}:${port}`);

  return new Promise((resolve) => {
    const socket = new net.Socket();

    socket.setTimeout(5000); // 5 second timeout

    socket.on('connect', () => {
      console.log('✅ Database host is reachable');
      socket.destroy();
      resolve(true);
    });

    socket.on('timeout', () => {
      console.log('❌ Connection timed out');
      socket.destroy();
      resolve(false);
    });

    socket.on('error', (err) => {
      console.log(`❌ Connection error: ${err.message}`);
      resolve(false);
    });

    socket.on('close', () => {
      // Don't resolve here as we might have already resolved
    });

    socket.connect(parseInt(port), host);
  });
}

function testApiKey(url, apiKey, name, headers = {}) {
  return new Promise((resolve) => {
    console.log(`\nTesting ${name} API key...`);

    const options = {
      hostname: url.split('/')[0],
      path: '/' + url.split('/').slice(1).join('/'),
      method: 'GET',
      timeout: 5000,
      headers: {
        'Content-Type': 'application/json',
        ...headers
      }
    };

    // Set authorization header based on service
    if (name === 'Anthropic') {
      options.headers['x-api-key'] = apiKey;
      options.headers['anthropic-version'] = '2023-06-01';
      options.path = '/v1/complete'; // Simplified endpoint
    } else if (name === 'Stripe') {
      options.headers['Authorization'] = `Bearer ${apiKey}`;
    } else if (name === 'AWS') {
      // For AWS, we'll just check if the service is reachable
      options.path = '/';
    }

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 401 || res.statusCode === 403) {
          const statusMsg = res.statusCode === 200 ? 'valid' : 'invalid/forbidden';
          console.log(`✅ ${name} API is reachable (status: ${res.statusCode} - key is ${statusMsg})`);
          resolve(res.statusCode === 200);
        } else {
          console.log(`❌ ${name} API test failed with status: ${res.statusCode}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${name} API request failed: ${error.message}`);
      resolve(false);
    });

    req.on('timeout', () => {
      console.log(`❌ ${name} API request timed out`);
      req.destroy();
      resolve(false);
    });

    // For AWS, we don't send a body, but for Anthropic we need to send a minimal request
    if (name === 'Anthropic' && apiKey) {
      req.write(JSON.stringify({
        prompt: '\n\nHuman: Hello\n\nAssistant:',
        max_tokens_to_sample: 1,
        model: 'claude-2'
      }));
    }

    req.end();
  });
}

