const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

const config = require('./config');

const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(xss()); // Sanitize user input to prevent XSS
app.use(mongoSanitize()); // Prevent MongoDB operator injection
app.use(hpp()); // Prevent HTTP Parameter Pollution

// Body parsing with limits from config
app.use(express.json({ limit: config.security.payloadLimit }));
app.use(express.urlencoded({ extended: true, limit: config.security.payloadLimit }));

